export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  let committed = clone(d.initial),
    draft = clone(d.initial);
  let past = [],
    future = [];
  const out = [];
  for (const op of d.operations) {
    if (op.op === "set") draft = clone(op.value);
    else if (op.op === "put") draft[op.key] = clone(op.value);
    else if (op.op === "delete") delete draft[op.key];
    else if (op.op === "commit") {
      if (
        Object.keys(draft).length !== Object.keys(committed).length ||
        Object.keys(draft).some((k) => draft[k] !== committed[k])
      ) {
        past.push(clone(committed));
        committed = clone(draft);
        future = [];
      }
    } else if (op.op === "undo") {
      draft = clone(committed);
      if (past.length) {
        future.push(clone(committed));
        committed = past.pop();
        draft = clone(committed);
      }
    } else if (op.op === "redo") {
      draft = clone(committed);
      if (future.length) {
        past.push(clone(committed));
        committed = future.pop();
        draft = clone(committed);
      }
    }
    out.push({ draft: clone(draft), committed: clone(committed) });
  }
  return out;
}

